// WP-5.1 mesh-shader visibility path: see include/fuse/renderer/meshlet/meshlet_path.hpp.
#include <fuse/renderer/meshlet/meshlet_path.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp51.cmake from shaders/meshlet/* (+ the WP-1.4 fragment shaders):
// kMeshlet<Kernel><Slang|Glsl>Spv and FUSE_MESHLET_{SLANG,GLSL} when every kernel of a language exists.
#include "meshlet_spv.h"
#endif

namespace fuse::renderer::meshlet {

namespace {
constexpr u32 kDrawPushBytes = sizeof(MeshletDrawPush);
constexpr u32 kExpandPushBytes = sizeof(MeshletExpandPush);
/// Counts words reset at the start of every frame: both task commands {0, 1, 1}, counters 0.
constexpr u32 kCountReset[kMeshletCountWords] = {0u, 1u, 1u, 0u, 1u, 1u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u};
constexpr u64 kCountBytes = sizeof(kCountReset);
constexpr u64 kTaskCommandBytes = 12u; // VkDrawMeshTasksIndirectCommandEXT
static_assert(kMeshletCountTasks1 * sizeof(u32) == kTaskCommandBytes, "region-1 task command follows region 0's");

enum RefIndex : u32 { kRefGroups = 0, kRefMasks, kRefCounts, kRefResults, kRefConstants };

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
struct KernelSet {
    Code expand, task, mesh, rasterFs, atomicFsImage, atomicFsBuffer;
};
#endif
} // namespace

MeshletPathSelection selectMeshletPath(const RendererCaps& caps, MeshletPathMode mode) {
    MeshletPathSelection s{};
    if (mode == MeshletPathMode::Indirect) {
        s.reason = "MeshletPathMode::Indirect requested";
    } else if (!caps.valid) {
        s.reason = "no device capabilities (stub backend or no device)";
    } else if (!caps.atLeast(RenderTier::T1)) {
        s.reason = caps.hardwareTier >= RenderTier::T1 ? "effective tier T0 (tier cap masks mesh shaders)"
                                                        : "device is T0 (no VK_EXT_mesh_shader)";
    } else if (!caps.taskShader || !caps.meshShader) {
        s.reason = "taskShader / meshShader not enabled";
    } else {
        s.meshShaders = true;
        s.reason = "ok";
    }
    return s;
}

MeshletCapabilities queryMeshletCapabilities(const VulkanDevice* device) {
    MeshletCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const visbuffer::VisCapabilities vis = visbuffer::queryVisCapabilities(device);
    if (!vis.raster) {
        c.reason = vis.rasterReason;
        return c;
    }
    const MeshletPathSelection s = selectMeshletPath(device->info().caps, MeshletPathMode::Auto);
    if (!s.meshShaders) {
        c.reason = s.reason;
        return c;
    }
    VkPhysicalDeviceMeshShaderPropertiesEXT mesh{};
    mesh.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_MESH_SHADER_PROPERTIES_EXT;
    VkPhysicalDeviceProperties2 props{};
    props.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2;
    props.pNext = &mesh;
    vkGetPhysicalDeviceProperties2(static_cast<VkPhysicalDevice>(device->nativePhysicalDevice()), &props);
    c.maxTaskGroups = mesh.maxTaskWorkGroupCount[0];
    c.maxMeshOutputVertices = mesh.maxMeshOutputVertices;
    c.maxMeshOutputPrimitives = mesh.maxMeshOutputPrimitives;
    if (mesh.maxMeshOutputVertices < kMeshletMaxVertices || mesh.maxMeshOutputPrimitives < kMeshletMaxTriangles ||
        mesh.maxTaskPayloadSize < sizeof(u32) * (kMeshletTaskGroup + 1u) || mesh.maxTaskWorkGroupSize[0] < kMeshletTaskGroup ||
        mesh.maxMeshWorkGroupSize[0] < kMeshletMeshThreads) {
        c.reason = "mesh-shader limits below the meshlet path's (64 v / 124 t outputs, 32 / 64 invocations)";
        return c;
    }
    c.meshPath = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

MeshletPath::~MeshletPath() { destroy(); }

bool MeshletPath::init(const MeshletPathDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.bindless == nullptr || desc.vis == nullptr ||
        !desc.vis->valid()) {
        return false;
    }
    const MeshletCapabilities caps = queryMeshletCapabilities(desc.device);
    if (desc.mode == MeshletPathMode::Indirect || !caps.meshPath) {
        if (desc.mode == MeshletPathMode::MeshShader) {
            return false;
        }
        const MeshletPathSelection s = selectMeshletPath(desc.device->info().caps, desc.mode);
        m_reason = s.meshShaders ? caps.reason : s.reason;
        m_mesh = false;
        m_initialized = true;
        return true;
    }
    m_initialized = true; // destroy() releases partial state from here on
    m_mesh = true;
    m_reason = "ok";
    m_capacity = desc.groupCapacity < caps.maxTaskGroups ? desc.groupCapacity : caps.maxTaskGroups;
    m_capacity = m_capacity > 0u ? m_capacity : 1u;
    const u32 frames = desc.framesInFlight > 0u ? desc.framesInFlight : 1u;
    const bool ok = createPipelines() &&
                    createBuffer(m_groups, 2ull * m_capacity * sizeof(MeshletGroup), false, false, "meshlet.groups") &&
                    createBuffer(m_masks, static_cast<u64>(m_capacity) * sizeof(u32), false, false, "meshlet.masks") &&
                    createBuffer(m_counts, kCountBytes, true, false, "meshlet.counts") &&
                    createBuffer(m_constantsRing, static_cast<u64>(frames) * sizeof(MeshletConstants), false, true,
                                 "meshlet.constants") &&
                    (!desc.results || createBuffer(m_results, 2ull * m_capacity * kMeshletTaskGroup * sizeof(u32), false,
                                                   false, "meshlet.results"));
    if (!ok) {
        const bool meshMode = desc.mode == MeshletPathMode::MeshShader;
        destroy();
        m_reason = "mesh-path resources could not be created";
        if (meshMode) {
            return false;
        }
        // Auto: a missing kernel language or resource falls back to the indirect path.
        m_desc = desc;
        m_initialized = true;
        return true;
    }
    m_stats.groupCapacity = m_capacity;
    return true;
#else
    m_reason = "stub backend";
    return false;
#endif
}

void MeshletPath::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    for (OwnedBuffer* b : {&m_groups, &m_masks, &m_counts, &m_results, &m_constantsRing}) {
        destroyBuffer(*b);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void* pipeline : {m_expandPipeline, m_drawPipeline}) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
        }
    }
    for (void* layout : {m_expandLayout, m_drawLayout}) {
        if (layout != nullptr) {
            vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(layout), nullptr);
        }
    }
#endif
    m_expandPipeline = m_drawPipeline = nullptr;
    m_expandLayout = m_drawLayout = nullptr;
    m_drawIndirect = nullptr;
    m_mesh = false;
    m_reason = "not initialised";
    m_language = "none";
    m_capacity = 0;
    m_ringSlot = 0;
    m_constantsAddress = 0;
    m_constants = MeshletConstants{};
    for (u8& q : m_queues) {
        q = rg::kNoQueue;
    }
    m_stats = MeshletStats{};
    m_initialized = false;
}

bool MeshletPath::createBuffer(OwnedBuffer& out, u64 bytes, bool indirect, bool hostVisible, const char* name) {
    out = OwnedBuffer{};
    BufferDesc desc{};
    desc.size = static_cast<usize>(bytes);
    desc.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::TransferDst) |
                                          static_cast<u32>(BufferUsage::TransferSrc) |
                                          static_cast<u32>(BufferUsage::ShaderDeviceAddress) |
                                          (indirect ? static_cast<u32>(BufferUsage::Indirect) : 0u));
    desc.memoryUsage = hostVisible ? MemoryUsage::CpuToGpu : MemoryUsage::GpuOnly;
    desc.name = name;
    if (!m_desc.allocator->createBuffer(desc, out.buffer) || out.buffer.deviceAddress == 0u ||
        (hostVisible && out.buffer.mapped == nullptr)) {
        if (out.buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(out.buffer);
        }
        out = OwnedBuffer{};
        return false;
    }
    out.slot = m_desc.bindless->registerBufferSlot(out.buffer, false);
    out.handle = m_desc.bindless->shaderHandle(out.slot);
    return out.slot.isValid();
}

void MeshletPath::destroyBuffer(OwnedBuffer& buffer) {
    if (buffer.slot.isValid()) {
        m_desc.bindless->unregisterSlot(buffer.slot);
    }
    if (buffer.buffer.handle != nullptr) {
        m_desc.allocator->destroyBuffer(buffer.buffer);
    }
    buffer = OwnedBuffer{};
}

bool MeshletPath::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    KernelSet k{};
    bool found = false;
#if defined(FUSE_MESHLET_SLANG)
    if (m_desc.language == MeshletKernelLanguage::Auto || m_desc.language == MeshletKernelLanguage::Slang) {
        k = KernelSet{code(kMeshletExpandSlangSpv),   code(kMeshletTaskSlangSpv),          code(kMeshletMeshSlangSpv),
                      code(kMeshletRasterFsSlangSpv), code(kMeshletAtomicFsImageSlangSpv), code(kMeshletAtomicFsBufferSlangSpv)};
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_MESHLET_GLSL)
    if (!found && (m_desc.language == MeshletKernelLanguage::Auto || m_desc.language == MeshletKernelLanguage::Glsl)) {
        k = KernelSet{code(kMeshletExpandGlslSpv),   code(kMeshletTaskGlslSpv),          code(kMeshletMeshGlslSpv),
                      code(kMeshletRasterFsGlslSpv), code(kMeshletAtomicFsImageGlslSpv), code(kMeshletAtomicFsBufferGlslSpv)};
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    m_drawIndirect = reinterpret_cast<void*>(vkGetDeviceProcAddr(device, "vkCmdDrawMeshTasksIndirectEXT"));
    if (m_drawIndirect == nullptr) {
        return false;
    }
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    auto makeLayout = [&](VkShaderStageFlags stages, u32 bytes, void*& out) {
        VkPushConstantRange range{stages, 0, bytes};
        VkPipelineLayoutCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
        info.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
        info.pSetLayouts = &setLayout;
        info.pushConstantRangeCount = 1;
        info.pPushConstantRanges = &range;
        VkPipelineLayout layout = VK_NULL_HANDLE;
        const bool ok = vkCreatePipelineLayout(device, &info, nullptr, &layout) == VK_SUCCESS;
        out = layout;
        return ok;
    };
    if (!makeLayout(VK_SHADER_STAGE_COMPUTE_BIT, kExpandPushBytes, m_expandLayout) ||
        !makeLayout(VK_SHADER_STAGE_TASK_BIT_EXT | VK_SHADER_STAGE_MESH_BIT_EXT | VK_SHADER_STAGE_FRAGMENT_BIT, kDrawPushBytes,
                    m_drawLayout)) {
        return false;
    }
    auto module = [&](const Code& c) {
        VkShaderModuleCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        info.codeSize = c.bytes;
        info.pCode = c.words;
        VkShaderModule m = VK_NULL_HANDLE;
        vkCreateShaderModule(device, &info, nullptr, &m);
        return m;
    };
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    // Expand (compute).
    {
        VkShaderModule m = module(k.expand);
        if (m == VK_NULL_HANDLE) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = m;
        info.stage.pName = "main";
        info.layout = static_cast<VkPipelineLayout>(m_expandLayout);
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, m, nullptr);
        m_expandPipeline = pipeline;
        if (result != VK_SUCCESS) {
            return false;
        }
    }
    // Task + mesh + the WP-1.4 fragment shader of the VisBuffer's mode / target.
    const bool atomic = m_desc.vis->mode() == visbuffer::VisMode::Atomic64;
    const Code& fsCode = !atomic ? k.rasterFs
                                 : (m_desc.vis->atomicTarget() == visbuffer::VisAtomicTarget::Image ? k.atomicFsImage
                                                                                                     : k.atomicFsBuffer);
    VkShaderModule ts = module(k.task);
    VkShaderModule ms = module(k.mesh);
    VkShaderModule fs = module(fsCode);
    if (ts == VK_NULL_HANDLE || ms == VK_NULL_HANDLE || fs == VK_NULL_HANDLE) {
        vkDestroyShaderModule(device, ts, nullptr);
        vkDestroyShaderModule(device, ms, nullptr);
        vkDestroyShaderModule(device, fs, nullptr);
        return false;
    }
    VkPipelineShaderStageCreateInfo stages[3]{};
    const VkShaderStageFlagBits stageBits[3] = {VK_SHADER_STAGE_TASK_BIT_EXT, VK_SHADER_STAGE_MESH_BIT_EXT,
                                                VK_SHADER_STAGE_FRAGMENT_BIT};
    const VkShaderModule modules[3] = {ts, ms, fs};
    for (u32 i = 0; i < 3u; ++i) {
        stages[i].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        stages[i].stage = stageBits[i];
        stages[i].module = modules[i];
        stages[i].pName = "main";
    }
    VkPipelineViewportStateCreateInfo viewport{};
    viewport.sType = VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO;
    viewport.viewportCount = 1;
    viewport.scissorCount = 1;
    VkPipelineRasterizationStateCreateInfo rasterization{};
    rasterization.sType = VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO;
    rasterization.polygonMode = VK_POLYGON_MODE_FILL;
    rasterization.cullMode = VK_CULL_MODE_NONE; // == the WP-1.4 pipelines (two-sided)
    rasterization.lineWidth = 1.f;
    VkPipelineMultisampleStateCreateInfo multisample{};
    multisample.sType = VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO;
    multisample.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;
    VkPipelineDepthStencilStateCreateInfo depth{};
    depth.sType = VK_STRUCTURE_TYPE_PIPELINE_DEPTH_STENCIL_STATE_CREATE_INFO;
    depth.depthTestEnable = atomic ? VK_FALSE : VK_TRUE;
    depth.depthWriteEnable = atomic ? VK_FALSE : VK_TRUE;
    depth.depthCompareOp = VK_COMPARE_OP_LESS;
    VkPipelineColorBlendAttachmentState blendAttachment{};
    blendAttachment.colorWriteMask = VK_COLOR_COMPONENT_R_BIT | VK_COLOR_COMPONENT_G_BIT;
    VkPipelineColorBlendStateCreateInfo blend{};
    blend.sType = VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO;
    blend.attachmentCount = atomic ? 0u : 1u;
    blend.pAttachments = atomic ? nullptr : &blendAttachment;
    const VkDynamicState dynamics[2] = {VK_DYNAMIC_STATE_VIEWPORT, VK_DYNAMIC_STATE_SCISSOR};
    VkPipelineDynamicStateCreateInfo dynamic{};
    dynamic.sType = VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO;
    dynamic.dynamicStateCount = 2;
    dynamic.pDynamicStates = dynamics;
    const VkFormat colorFormat = static_cast<VkFormat>(visbuffer::kVisRasterFormat);
    VkPipelineRenderingCreateInfo rendering{};
    rendering.sType = VK_STRUCTURE_TYPE_PIPELINE_RENDERING_CREATE_INFO;
    rendering.colorAttachmentCount = atomic ? 0u : 1u;
    rendering.pColorAttachmentFormats = atomic ? nullptr : &colorFormat;
    rendering.depthAttachmentFormat = atomic ? VK_FORMAT_UNDEFINED : static_cast<VkFormat>(visbuffer::kVisDepthFormat);
    VkGraphicsPipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO;
    info.pNext = &rendering;
    info.flags = createFlags;
    info.stageCount = 3;
    info.pStages = stages;
    info.pViewportState = &viewport;
    info.pRasterizationState = &rasterization;
    info.pMultisampleState = &multisample;
    info.pDepthStencilState = &depth;
    info.pColorBlendState = &blend;
    info.pDynamicState = &dynamic;
    info.layout = static_cast<VkPipelineLayout>(m_drawLayout);
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateGraphicsPipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    for (VkShaderModule m : modules) {
        vkDestroyShaderModule(device, m, nullptr);
    }
    m_drawPipeline = pipeline;
    return result == VK_SUCCESS;
#else
    return false;
#endif
}

bool MeshletPath::beginFrame(u64 frameSerial, const MeshletFrameDesc& frame, const culling::InstanceCuller& culler) {
    if (!m_initialized) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_stats.drawPasses = 0;
    if (!m_mesh) {
        return true;
    }
    const visbuffer::VisBuffer& vis = *m_desc.vis;
    MeshletConstants& c = m_constants;
    c.cull = culler.constants();
    c.camera[0] = frame.camera[0];
    c.camera[1] = frame.camera[1];
    c.camera[2] = frame.camera[2];
    c.flags = (frame.frustum ? static_cast<u32>(kMeshletCullFrustum) : 0u) | (frame.cone ? static_cast<u32>(kMeshletCullCone) : 0u) |
              (frame.occlusion ? static_cast<u32>(kMeshletCullOcclusion) : 0u) |
              (frame.results && m_results.handle != 0u ? static_cast<u32>(kMeshletWriteResults) : 0u);
    c.groupsBuffer = m_groups.handle;
    c.masksBuffer = m_masks.handle;
    c.countsBuffer = m_counts.handle;
    c.resultsBuffer = m_results.handle;
    c.groupCapacity = m_capacity;
    c.scene = frame.sceneHandle;
    const u32 frames = static_cast<u32>(m_constantsRing.buffer.desc.size / sizeof(MeshletConstants));
    m_ringSlot = frames > 0u ? (m_ringSlot + 1u) % frames : 0u;
    const u64 offset = static_cast<u64>(m_ringSlot) * sizeof(MeshletConstants);
    std::memcpy(static_cast<u8*>(m_constantsRing.buffer.mapped) + offset, &c, sizeof(MeshletConstants));
    m_constantsAddress = m_constantsRing.buffer.deviceAddress + offset;
    MeshletDrawPush& p = m_push;
    std::memcpy(p.viewProj, frame.viewProj, sizeof(p.viewProj));
    p.scene = frame.sceneHandle;
    p.target64 = vis.target64Handle();
    p.width = vis.width();
    p.height = vis.height();
    p.constants = m_constantsAddress;
    p.mode = kMeshletModeEarly;
    return vis.width() > 0u && vis.height() > 0u;
}

MeshletGraphRefs MeshletPath::importInto(rg::Graph& graph) {
    MeshletGraphRefs refs{};
    if (!m_initialized || !m_mesh) {
        return refs;
    }
    auto import = [&](OwnedBuffer& b, u32 index, const char* name) {
        if (b.buffer.handle == nullptr) {
            return rg::BufferRef{};
        }
        return graph.importBuffer(rg::ImportedBuffer{b.buffer.handle, b.buffer.desc.size, m_queues[index], &m_queues[index], name});
    };
    refs.groups = import(m_groups, kRefGroups, "meshlet.groups");
    refs.masks = import(m_masks, kRefMasks, "meshlet.masks");
    refs.counts = import(m_counts, kRefCounts, "meshlet.counts");
    refs.results = import(m_results, kRefResults, "meshlet.results");
    refs.constants = import(m_constantsRing, kRefConstants, "meshlet.constants");
    return refs;
}

void MeshletPath::addDraw(rg::Graph& graph, const MeshletGraphRefs& refs, const visbuffer::VisGraphRefs& vis,
                          const gpu_scene::GpuSceneGraphRefs& scene, const culling::InstanceCuller& culler,
                          const culling::CullGraphRefs& cullRefs, culling::CullPhase phase) {
    if (!m_initialized) {
        return;
    }
    const bool phase1 = phase == culling::CullPhase::Phase1;
    if (!m_mesh) {
        m_desc.vis->addDraw(graph, vis, scene, culler, cullRefs, phase, phase1);
        ++m_stats.drawPasses;
        return;
    }
    if (!refs.counts.valid() || !vis.vis.valid()) {
        return;
    }
    const u32 region = phase1 ? 0u : 1u;
    constexpr u8 kTaskMesh = static_cast<u8>(rg::kStageTask | rg::kStageMesh);
    if (phase1) {
        graph.addPass("meshlet.reset", &MeshletPath::recordReset, this).use(refs.counts, rg::Access::TransferDst);
    }
    // Expand: the culler's phase draws -> task-group records of this region + its task command.
    ExpandRecord& e = m_expand[region];
    e.self = this;
    e.push = MeshletExpandPush{};
    e.push.constants = m_constantsAddress;
    e.push.phase = region + 1u;
    e.push.maxDraws = culler.capacity();
    e.groups = (culler.capacity() + kMeshletExpandWorkgroup - 1u) / kMeshletExpandWorkgroup;
    rg::PassBuilder expand = graph.addPass(phase1 ? "meshlet.expand1" : "meshlet.expand2", &MeshletPath::recordExpand, &e);
    gpu_scene::GpuScene::useAll(expand, scene, rg::Access::StorageRead, rg::kStageCompute);
    expand.use(refs.constants, rg::Access::StorageRead, {}, rg::kStageCompute)
        .use(refs.counts, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
        .use(refs.groups, rg::Access::StorageWrite,
             rg::BufferRange{static_cast<u64>(region) * m_capacity * sizeof(MeshletGroup), static_cast<u64>(m_capacity) * sizeof(MeshletGroup)},
             rg::kStageCompute)
        .use(cullRefs.args, rg::Access::StorageRead, {}, rg::kStageCompute)
        .use(cullRefs.counts, rg::Access::StorageRead, {}, rg::kStageCompute);
    // Draw.
    const bool atomic = m_desc.vis->mode() == visbuffer::VisMode::Atomic64;
    if (phase1 && atomic) {
        m_desc.vis->addClear(graph, vis);
    }
    DrawRecord& d = m_draws[region];
    d.self = this;
    d.vis = vis.vis;
    d.depth = vis.depth;
    d.clear = phase1;
    d.phase2 = !phase1;
    ++m_stats.drawPasses;
    rg::PassBuilder draw = graph.addPass(phase1 ? "meshlet.phase1" : "meshlet.phase2", &MeshletPath::recordDraw, &d);
    gpu_scene::GpuScene::useAll(draw, scene, rg::Access::StorageRead, kTaskMesh);
    // Phase 2 runs region 0 again (late) and region 1: the whole groups buffer; phase 1 only region 0.
    draw.use(refs.constants, rg::Access::StorageRead, {}, kTaskMesh)
        .use(refs.counts, rg::Access::IndirectRead)
        .use(refs.counts, rg::Access::StorageReadWrite, {}, rg::kStageTask)
        .use(refs.groups, rg::Access::StorageRead,
             phase1 ? rg::BufferRange{0, static_cast<u64>(m_capacity) * sizeof(MeshletGroup)} : rg::BufferRange{},
             rg::kStageTask)
        .use(refs.masks, rg::Access::StorageReadWrite, {}, rg::kStageTask);
    if (refs.results.valid()) {
        draw.use(refs.results, rg::Access::StorageReadWrite, {}, rg::kStageTask);
    }
    const u32 needHistory = culling::kCullOcclusion | culling::kCullHistoryValid;
    const bool hiz = (m_constants.flags & kMeshletCullOcclusion) != 0u &&
                     (phase1 ? (m_constants.cull.flags & needHistory) == needHistory
                             : (m_constants.cull.flags & culling::kCullOcclusion) != 0u);
    if (hiz && cullRefs.hiz.valid()) {
        draw.use(cullRefs.hiz, rg::Access::SampledRead, {}, rg::kStageTask);
    }
    if (atomic) {
        if (vis.image64.valid()) {
            draw.use(vis.image64, rg::Access::StorageReadWrite, {}, rg::kStageFragment);
        }
        if (vis.buffer64.valid()) {
            draw.use(vis.buffer64, rg::Access::StorageReadWrite, {}, rg::kStageFragment);
        }
    } else {
        draw.use(vis.vis, rg::Access::ColorAttachmentWrite).use(vis.depth, rg::Access::DepthAttachmentWrite);
    }
}

void MeshletPath::addCulledFrame(rg::Graph& graph, const MeshletGraphRefs& refs, const visbuffer::VisGraphRefs& vis,
                                 const gpu_scene::GpuSceneGraphRefs& scene, u32 sceneHandle, culling::InstanceCuller& culler,
                                 const culling::CullGraphRefs& cullRefs) {
    if (!m_initialized) {
        return;
    }
    if (!m_mesh) {
        m_desc.vis->addCulledFrame(graph, vis, scene, sceneHandle, culler, cullRefs);
        m_stats.drawPasses += 2u;
        return;
    }
    visbuffer::VisBuffer& vb = *m_desc.vis;
    culler.addPhase1(graph, cullRefs, scene, sceneHandle);
    addDraw(graph, refs, vis, scene, culler, cullRefs, culling::CullPhase::Phase1);
    vb.addExport(graph, vis);
    culler.addHizBuild(graph, cullRefs, vis.depth, vb.depthSampledHandle());
    culler.addPhase2(graph, cullRefs, scene, sceneHandle);
    addDraw(graph, refs, vis, scene, culler, cullRefs, culling::CullPhase::Phase2);
    vb.addExport(graph, vis);
    culler.addHizBuild(graph, cullRefs, vis.depth, vb.depthSampledHandle());
}

void MeshletPath::recordReset(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const MeshletPath& self = *static_cast<const MeshletPath*>(user);
    vkCmdUpdateBuffer(static_cast<VkCommandBuffer>(context.commandBuffer), static_cast<VkBuffer>(self.m_counts.buffer.handle), 0,
                      kCountBytes, kCountReset);
#else
    (void)context;
    (void)user;
#endif
}

void MeshletPath::recordExpand(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const ExpandRecord& r = *static_cast<const ExpandRecord*>(user);
    const MeshletPath& self = *r.self;
    if (r.groups == 0u) {
        return;
    }
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_expandPipeline));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_expandLayout, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_expandLayout), VK_SHADER_STAGE_COMPUTE_BIT, 0, kExpandPushBytes,
                       &r.push);
    vkCmdDispatch(cmd, r.groups, 1, 1);
#else
    (void)context;
    (void)user;
#endif
}

void MeshletPath::recordDraw(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const DrawRecord& r = *static_cast<const DrawRecord*>(user);
    const MeshletPath& self = *r.self;
    const bool atomic = self.m_desc.vis->mode() == visbuffer::VisMode::Atomic64;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    const u32 width = self.m_push.width;
    const u32 height = self.m_push.height;
    VkRenderingAttachmentInfo color{};
    color.sType = VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO;
    VkRenderingAttachmentInfo depth{};
    depth.sType = VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO;
    VkRenderingInfo rendering{};
    rendering.sType = VK_STRUCTURE_TYPE_RENDERING_INFO;
    rendering.renderArea.extent = {width, height};
    rendering.layerCount = 1;
    if (!atomic) {
        color.imageView = static_cast<VkImageView>(context.imageView(r.vis));
        color.imageLayout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
        color.loadOp = r.clear ? VK_ATTACHMENT_LOAD_OP_CLEAR : VK_ATTACHMENT_LOAD_OP_LOAD;
        color.storeOp = VK_ATTACHMENT_STORE_OP_STORE;
        color.clearValue.color.uint32[0] = visbuffer::kVisInvalid;
        color.clearValue.color.uint32[1] = visbuffer::kVisInvalid;
        depth.imageView = static_cast<VkImageView>(context.imageView(r.depth));
        depth.imageLayout = VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL;
        depth.loadOp = r.clear ? VK_ATTACHMENT_LOAD_OP_CLEAR : VK_ATTACHMENT_LOAD_OP_LOAD;
        depth.storeOp = VK_ATTACHMENT_STORE_OP_STORE;
        depth.clearValue.depthStencil.depth = 1.f;
        rendering.colorAttachmentCount = 1;
        rendering.pColorAttachments = &color;
        rendering.pDepthAttachment = &depth;
    }
    vkCmdBeginRendering(cmd, &rendering);
    const VkPipelineLayout layout = static_cast<VkPipelineLayout>(self.m_drawLayout);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, static_cast<VkPipeline>(self.m_drawPipeline));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, self.m_drawLayout, 0);
    const VkViewport viewport{0.f, 0.f, static_cast<f32>(width), static_cast<f32>(height), 0.f, 1.f};
    const VkRect2D scissor{{0, 0}, {width, height}};
    vkCmdSetViewport(cmd, 0, 1, &viewport);
    vkCmdSetScissor(cmd, 0, 1, &scissor);
    const auto drawIndirect = reinterpret_cast<PFN_vkCmdDrawMeshTasksIndirectEXT>(self.m_drawIndirect);
    const VkBuffer counts = static_cast<VkBuffer>(self.m_counts.buffer.handle);
    const VkShaderStageFlags stages = VK_SHADER_STAGE_TASK_BIT_EXT | VK_SHADER_STAGE_MESH_BIT_EXT | VK_SHADER_STAGE_FRAGMENT_BIT;
    MeshletDrawPush push = self.m_push;
    if (!r.phase2) {
        push.mode = kMeshletModeEarly;
        vkCmdPushConstants(cmd, layout, stages, 0, kDrawPushBytes, &push);
        drawIndirect(cmd, counts, kMeshletCountTasks0 * sizeof(u32), 1, static_cast<u32>(kTaskCommandBytes));
    } else {
        // Late (region 0's deferred meshlets, same task command), then the culler's phase-2 instances.
        push.mode = kMeshletModeLate;
        vkCmdPushConstants(cmd, layout, stages, 0, kDrawPushBytes, &push);
        drawIndirect(cmd, counts, kMeshletCountTasks0 * sizeof(u32), 1, static_cast<u32>(kTaskCommandBytes));
        push.mode = kMeshletModePhase2;
        vkCmdPushConstants(cmd, layout, stages, 0, kDrawPushBytes, &push);
        drawIndirect(cmd, counts, kMeshletCountTasks1 * sizeof(u32), 1, static_cast<u32>(kTaskCommandBytes));
    }
    vkCmdEndRendering(cmd);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::meshlet
